# Global verbosity
VERBOSITY = 0

def log_timestamp():
    dt = datetime.datetime.utcnow()
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def log(level, module, msg):
    # level: ERROR, WARN, INFO, DEBUG, TRACE
    # verbosity mapping: 0 warn (show WARN,ERROR), 1 info (+INFO), 2 debug (+DEBUG), 3+ trace (+TRACE)
    global VERBOSITY
    order = {"ERROR": 0, "WARN": 1, "INFO": 2, "DEBUG": 3, "TRACE": 4}
    # threshold based on verbosity: 0->WARN(1), 1->INFO(2), 2->DEBUG(3), 3->TRACE(4), 4->TRACE all?
    # Actually -vvvv is trace all, but we treat same as trace
    if VERBOSITY == 0:
        thresh = 1
    elif VERBOSITY == 1:
        thresh = 2
    elif VERBOSITY == 2:
        thresh = 3
    else:
        thresh = 4
    if order.get(level, 99) > thresh:
        return
    ts = log_timestamp()
    # format: [ts LEVEL module] msg with level padded to 5
    sys.stderr.write(f"[{ts} {level:<5} {module}] {msg}\n")
    sys.stderr.flush()

def log_always(level, module, msg):
    ts = log_timestamp()
    sys.stderr.write(f"[{ts} {level:<5} {module}] {msg}\n")
    sys.stderr.flush()

PYEOF
echo done
